style.css:
@-moz-document domain("youtube.com") {
/* الخلفية العامة */
    body,
    html,
    ytd-app {
        background-color: #ffe6f0; /* وردي فاتح جداً */
        color: #5c5c5c; /* نص رمادي ناعم */
    }

    /* شريط التنقل العلوي */
    ytd-masthead {
        background-color: #ffb3cc; /* وردي متوسط */
        border-bottom: 1px solid #ff99bb;
    }

    /* أيقونات وأزرار شريط التنقل */
    ytd-masthead #buttons ytd-button-renderer yt-icon-button,
    ytd-masthead #container yt-icon-button {
        color: #800020; /* وردي غامق */
    }

    /* حقل البحث */
    #search-input.ytd-searchbox,
    #search-form.ytd-searchbox {
        background-color: #ffffff;
        border: 1px solid #ff99bb;
        border-radius: 20px;
    }

    #search-icon-legacy.ytd-searchbox {
        color: #800020;
    }

    /* القائمة الجانبية (Sidebar) */
    ytd-mini-guide-renderer,
    ytd-guide-renderer {
        background-color: #ffcccc; /* وردي فاتح */
        border-right: 1px solid #ffb3cc;
    }

    /* روابط القائمة الجانبية وعناصرها */
    ytd-guide-entry-renderer a,
    ytd-mini-guide-entry-renderer a {
        color: #5c5c5c;
    }

    ytd-guide-entry-renderer[selected] a,
    ytd-mini-guide-entry-renderer[selected] a {
        background-color: #ff99bb; /* وردي أغمق قليلاً للعنصر المحدد */
        color: #ffffff;
    }

    /* خلفية الفيديوهات المصغرة (Thumbnails) والعناوين */
    ytd-grid-video-renderer,
    ytd-compact-video-renderer,
    ytd-video-renderer,
    ytd-playlist-video-renderer,
    ytd-rich-grid-video-renderer {
        background-color: #ffffff; /* خلفية بيضاء للفيديوهات */
        border-radius: 8px;
        box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05);
    }

    /* عناوين الفيديوهات */
    yt-formatted-string.ytd-video-renderer,
    yt-formatted-string.ytd-playlist-video-renderer,
    yt-formatted-string.ytd-compact-video-renderer,
    yt-formatted-string.ytd-rich-grid-video-renderer {
        color: #800020; /* لون وردي غامق للعناوين */
    }

    /* أسماء القنوات وعدد المشاهدات */
    ytd-channel-name yt-formatted-string,
    yt-formatted-string.ytd-badge-supported-renderer,
    span.ytd-video-meta-block {
        color: #a3667f; /* وردي بنفسجي ناعم */
    }

    /* أزرار التشغيل والإعجاب والاشتراك */
    yt-button-shape button {
        background-color: #ff99bb; /* وردي متوسط */
        color: #ffffff;
        border-radius: 5px;
    }

    yt-button-shape button:hover {
        background-color: #ff6699; /* وردي أغمق عند التمرير */
    }

    /* شريط التقدم (Progress bar) للفيديو */
    /* تمت إزالة !important للسماح للثيمات الأخرى بالتأثير */
    .ytp-play-progress.ytp-swatch-color,
    .ytp-volume-slider-handle.ytp-swatch-color {
        background-color: #ff6699; /* وردي نابض */
    }

    .ytp-scrubber-button.ytp-swatch-background-color {
        background-color: #ff6699;
    }

    /* التعليقات */
    ytd-comments-header-renderer,
    ytd-comment-thread-renderer {
        background-color: #ffebe6; /* وردي فاتح جداً للخلفية */
        border-radius: 10px;
        padding: 10px;
        margin-bottom: 10px;
    }

    /* نص التعليقات */
    ytd-comment-renderer #content-text {
        color: #5c5c5c;
    }

    /* أسماء المستخدمين في التعليقات */
    ytd-comment-renderer #author-text {
        color: #800020;
    }

    /* الأزرار العامة في الموقع */
    paper-button {
        background-color: #ff99bb;
        color: #ffffff;
        border-radius: 5px;
    }

    paper-button:hover {
        background-color: #ff6699;
    }

    /* الأشرطة التمريرية (Scrollbars) - قد لا تعمل على جميع المتصفحات */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-track {
        background: #ffe6f0;
    }

    ::-webkit-scrollbar-thumb {
        background: #ff99bb;
        border-radius: 5px;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #ff6699;
    }
}
